mapper.select:
SELECT 
FROM music_log
WHERE member_id = #{memberId}

  AND (
    track_name LIKE CONCAT('%', #{keyword}, '%')
    OR artist_name LIKE CONCAT('%', #{keyword}, '%')
    OR album_name LIKE CONCAT('%', #{keyword}, '%')
    OR genre LIKE CONCAT('%', #{keyword}, '%')
    OR tags LIKE CONCAT('%', #{keyword}, '%')
    OR memo LIKE CONCAT('%', #{keyword}, '%')
  )

AND listened_date >= #{from}
AND listened_date <= #{to}
ORDER BY listened_date DESC, music_log_id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT 
FROM music_log
WHERE music_log_id = #{musicLogId}
  AND member_id = #{memberId}

